import { useEffect, useState, type FormEvent } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { Alert, Button, Card, Empty, Input, Modal, Select, Table, Tag, Typography } from 'antd';
import { useSearchParams } from 'react-router-dom';
import { confirmAssistantPreview, createAssistantPreview, getAssistantPreview, notifyAuthExpired, UnknownConfirmationError, type AssistantPreviewDraft } from './assistant-client.js';

const { Text, Title } = Typography;
const TOKEN_KEY = 'pianomanager.accessToken';

type Section = 'students' | 'schedule' | 'finance';
type Student = { id: string; name: string; phone: string | null; notes: string | null; enrollmentStatus: string; createdAt: string; updatedAt: string };
type Teacher = { id: string; name: string; isActive: boolean };
type CourseAccount = { id: string; courseId: string; courseName: string; defaultDurationMinutes: number; currentUnitPrice: string; version: number };
type CourseAccountBalance = { accountId: string; paidBalance: string; giftBalance: string; totalBalance: string };
type CourseAccountLedger = { accountId: string; entries: Array<{ entryId: string; occurredAt: string; kind: string; amount: string; paidDelta: string; giftDelta: string; note: string | null; operator: string }> };
type Lesson = { id: string; accountId: string; teacherId: string; startsAt: string; endsAt: string; status: string; student: { id: string; name: string }; course: { id: string; name: string }; unitPriceSnapshot: string | null };
type Report = { periodStart: string; cashIncome: string; cashExpense: string; cashNet: string; lessonIncome: string; refundFeeIncome: string; manualIncome: string; payrollCost: string; giftCost: string; manualExpense: string; operatingProfit: string };
type Payroll = { id: string; teacherId: string; teacherName: string; periodStart: string; courseRevenue: string; baseSalary: string; commissionRate: string; commissionAmount: string; bonusAmount: string; deductionAmount: string; grossSalary: string; netSalary: string; status: 'UNPAID' | 'PAID'; paidAt: string | null; paymentChannel: string | null; version: number };
type ManualTransaction = { id: string; kind: 'INCOME' | 'EXPENSE'; incomeCategory: string | null; expenseCategory: string | null; amount: string; channel: string; occurredAt: string; note: string | null; createdAt: string };
type ClosedPeriod = { period: string; closedAt: string; reopenedAt: string | null; reopenReason: string | null };
type PeriodCloseReadiness = { period: string; closed: boolean; blockers: Array<{ code: string; count: number; message: string }>; pendingLessons: Array<{ lessonId: string; studentName: string; courseName: string; teacherName: string; endsAt: string }>; missingPayrollTeachers: Array<{ teacherId: string; teacherName: string }>; unpaidPayrolls: Array<{ payrollId: string; teacherId: string; teacherName: string; netSalary: string }>; refundAnomalies: Array<{ refundId: string; studentName: string; issue: string }>; ledgerAnomalies: Array<{ entryId: string; kind: string; issue: string }> };

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

function getToken(): string | null {
  return window.localStorage.getItem(TOKEN_KEY);
}

function idempotencyKey(): string {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') return crypto.randomUUID();
  throw new Error('当前浏览器不支持安全的幂等键生成');
}

async function request<T>(path: string, validate: (value: unknown) => value is T, init?: RequestInit): Promise<T> {
  const headers = new Headers(init?.headers);
  headers.set('Accept', 'application/json');
  const token = getToken();
  if (token) headers.set('Authorization', `Bearer ${token}`);
  if (init?.body) headers.set('Content-Type', 'application/json');
  const response = await fetch(path, { ...init, headers });
  if (!response.ok) {
    if (response.status === 401) {
      notifyAuthExpired();
      throw new Error('登录状态已失效，请重新登录后再试。');
    }
    if (response.status === 403) throw new Error('当前账号无权执行此操作。');
    throw new Error(`请求失败（HTTP ${response.status}）`);
  }
  if (response.status === 204) return undefined as T;
  const payload: unknown = await response.json();
  if (!validate(payload)) throw new Error('服务返回的数据格式无效');
  return payload;
}

function isList<T>(value: unknown, item: (value: unknown) => value is T): value is T[] { return Array.isArray(value) && value.every(item); }
function isStudent(value: unknown): value is Student { return isRecord(value) && typeof value.id === 'string' && typeof value.name === 'string' && (value.phone === undefined || value.phone === null || typeof value.phone === 'string') && (value.notes === null || typeof value.notes === 'string') && typeof value.enrollmentStatus === 'string' && typeof value.createdAt === 'string' && typeof value.updatedAt === 'string'; }
function isTeacher(value: unknown): value is Teacher { return isRecord(value) && typeof value.id === 'string' && typeof value.name === 'string' && typeof value.isActive === 'boolean'; }
function isAccount(value: unknown): value is CourseAccount { return isRecord(value) && typeof value.id === 'string' && typeof value.courseId === 'string' && typeof value.courseName === 'string' && typeof value.defaultDurationMinutes === 'number' && typeof value.currentUnitPrice === 'string' && typeof value.version === 'number'; }
function isBalance(value: unknown): value is CourseAccountBalance { return isRecord(value) && typeof value.accountId === 'string' && typeof value.paidBalance === 'string' && typeof value.giftBalance === 'string' && typeof value.totalBalance === 'string'; }
function isLedger(value: unknown): value is CourseAccountLedger { return isRecord(value) && typeof value.accountId === 'string' && Array.isArray(value.entries) && value.entries.every((entry) => isRecord(entry) && typeof entry.entryId === 'string' && typeof entry.occurredAt === 'string' && typeof entry.kind === 'string' && typeof entry.amount === 'string' && typeof entry.paidDelta === 'string' && typeof entry.giftDelta === 'string' && (entry.note === null || typeof entry.note === 'string') && typeof entry.operator === 'string'); }
function isLesson(value: unknown): value is Lesson { return isRecord(value) && typeof value.id === 'string' && typeof value.accountId === 'string' && typeof value.teacherId === 'string' && typeof value.startsAt === 'string' && typeof value.endsAt === 'string' && typeof value.status === 'string' && isRecord(value.student) && typeof value.student.id === 'string' && typeof value.student.name === 'string' && isRecord(value.course) && typeof value.course.id === 'string' && typeof value.course.name === 'string' && (value.unitPriceSnapshot === null || typeof value.unitPriceSnapshot === 'string'); }
function isReport(value: unknown): value is Report { return isRecord(value) && ['periodStart', 'cashIncome', 'cashExpense', 'cashNet', 'lessonIncome', 'refundFeeIncome', 'manualIncome', 'payrollCost', 'giftCost', 'manualExpense', 'operatingProfit'].every((key) => typeof value[key] === 'string'); }
function isPayroll(value: unknown): value is Payroll { return isRecord(value) && typeof value.id === 'string' && typeof value.teacherId === 'string' && typeof value.teacherName === 'string' && typeof value.periodStart === 'string' && typeof value.courseRevenue === 'string' && typeof value.baseSalary === 'string' && typeof value.commissionRate === 'string' && typeof value.commissionAmount === 'string' && typeof value.bonusAmount === 'string' && typeof value.deductionAmount === 'string' && typeof value.grossSalary === 'string' && typeof value.netSalary === 'string' && (value.status === 'UNPAID' || value.status === 'PAID') && (value.paidAt === null || typeof value.paidAt === 'string') && (value.paymentChannel === null || typeof value.paymentChannel === 'string') && typeof value.version === 'number'; }
function isManualTransaction(value: unknown): value is ManualTransaction { return isRecord(value) && typeof value.id === 'string' && (value.kind === 'INCOME' || value.kind === 'EXPENSE') && (value.incomeCategory === null || typeof value.incomeCategory === 'string') && (value.expenseCategory === null || typeof value.expenseCategory === 'string') && typeof value.amount === 'string' && typeof value.channel === 'string' && typeof value.occurredAt === 'string' && (value.note === null || typeof value.note === 'string') && typeof value.createdAt === 'string'; }
function isClosedPeriod(value: unknown): value is ClosedPeriod { return isRecord(value) && typeof value.period === 'string' && typeof value.closedAt === 'string' && (value.reopenedAt === null || typeof value.reopenedAt === 'string') && (value.reopenReason === null || typeof value.reopenReason === 'string'); }
function isPeriodCloseReadiness(value: unknown): value is PeriodCloseReadiness { return isRecord(value) && typeof value.period === 'string' && typeof value.closed === 'boolean' && Array.isArray(value.blockers) && value.blockers.every((item) => isRecord(item) && typeof item.code === 'string' && typeof item.count === 'number' && typeof item.message === 'string') && Array.isArray(value.pendingLessons) && Array.isArray(value.missingPayrollTeachers) && Array.isArray(value.unpaidPayrolls) && Array.isArray(value.refundAnomalies) && Array.isArray(value.ledgerAnomalies); }

function formatDate(value: string): string { const date = new Date(value); return Number.isNaN(date.getTime()) ? '时间无效' : new Intl.DateTimeFormat('zh-CN', { timeZone: 'Asia/Shanghai', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false }).format(date); }
function money(value: string): string { return `¥${value}`; }
function ledgerKind(value: string): string { return ({ PAYMENT: '交费', GIFT: '赠送', LESSON_CONSUMPTION: '课消', LESSON_CONSUMPTION_REVERSAL: '撤销课消', PAYMENT_REVERSAL: '交费冲正', GIFT_REVERSAL: '赠送冲正', REFUND_PAID: '退费', REFUND_GIFT_CLEARING: '赠送余额清零' } as Record<string, string>)[value] ?? value; }
function maskPhone(value: string | null): string { if (!value) return '—'; if (value.length <= 7) return `${value.slice(0, 2)}****${value.slice(-1)}`; return `${value.slice(0, 3)}****${value.slice(-4)}`; }
function monthNow(): string { return new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit' }).format(new Date()); }
function localNow(): string { const parts = new Intl.DateTimeFormat('sv-SE', { timeZone: 'Asia/Shanghai', dateStyle: 'short', timeStyle: 'short' }).format(new Date()); return parts.replace(' ', 'T'); }
function toOffsetDate(value: string): string { return value.length === 16 ? `${value}:00+08:00` : `${value}+08:00`; }
function businessDate(value = new Date()): string { return new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit' }).format(value); }
function addBusinessDays(dateText: string, days: number): string { const [year, month, day] = dateText.split('-').map(Number); const date = new Date(Date.UTC(year ?? 0, (month ?? 1) - 1, day ?? 1)); date.setUTCDate(date.getUTCDate() + days); return `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, '0')}-${String(date.getUTCDate()).padStart(2, '0')}`; }
function weekStart(offset = 0): string { const today = businessDate(); const [year, month, day] = today.split('-').map(Number); const date = new Date(Date.UTC(year ?? 0, (month ?? 1) - 1, day ?? 1)); const mondayOffset = (date.getUTCDay() + 6) % 7; return addBusinessDays(today, -mondayOffset + offset * 7); }

function browserIds(): { idempotencyKey: string; requestId: string } {
  return { idempotencyKey: idempotencyKey(), requestId: idempotencyKey() };
}

function useUrlState(key: string, fallback: string): [string, (value: string) => void] {
  const [params, setParams] = useSearchParams();
  const value = params.get(key) ?? fallback;
  const setValue = (next: string) => setParams((current) => {
    const updated = new URLSearchParams(current);
    if (!next || next === fallback) updated.delete(key); else updated.set(key, next);
    return updated;
  }, { replace: true });
  return [value, setValue];
}

function PreviewDialog({ preview, onCancel, onConfirm }: { preview: (AssistantPreviewDraft & { success: string; invalidate: string[] }) | null; onCancel: () => void; onConfirm: () => Promise<Record<string, unknown> | null> }) {
  const [status, setStatus] = useState<'checking' | 'pending' | 'confirming' | 'unknown' | 'executed'>('checking');
  const [message, setMessage] = useState('');
  const [receipt, setReceipt] = useState<Record<string, unknown> | null>(null);
  useEffect(() => {
    if (!preview) return undefined;
    let active = true;
    setStatus('checking'); setMessage(''); setReceipt(null);
    void getAssistantPreview({ token: getToken(), previewId: preview.previewId }).then((current) => {
      if (!active) return;
      if (current.actionType !== preview.actionType || current.schemaVersion !== preview.schemaVersion || current.schemaVersion !== `${current.actionType}.v1`) { setStatus('unknown'); setMessage('确认单版本或类型不受支持，请重新生成。'); }
      else if (current.status === 'EXECUTED') { setReceipt(current.receipt); setStatus('executed'); setMessage('操作已执行，以下为 Core 回执。'); }
      else if (current.status === 'PENDING') setStatus('pending');
      else { setStatus('unknown'); setMessage(`预览当前状态为 ${current.status}，请重新生成确认单。`); }
    }).catch((error: unknown) => { if (active) { setStatus('unknown'); setMessage(error instanceof Error ? error.message : '无法读取当前状态'); } });
    return () => { active = false; };
  }, [preview?.previewId]);
  const recheck = async () => {
    if (!preview) return;
    try {
      const current = await getAssistantPreview({ token: getToken(), previewId: preview.previewId });
      if (current.actionType !== preview.actionType || current.schemaVersion !== preview.schemaVersion || current.schemaVersion !== `${current.actionType}.v1`) { setStatus('unknown'); setMessage('确认单版本或类型不受支持，请重新生成。'); }
      else if (current.status === 'EXECUTED') { setReceipt(current.receipt); setStatus('executed'); setMessage('操作已执行，以下为 Core 回执。'); await onConfirm(); }
      else if (current.status === 'PENDING') { setStatus('pending'); setMessage('Core 当前显示待确认，请核对后决定是否重试。'); }
      else { setStatus('unknown'); setMessage(`预览当前状态为 ${current.status}，请重新生成确认单。`); }
    } catch (error) { setStatus('unknown'); setMessage(error instanceof Error ? error.message : '无法读取当前状态'); }
  };
  const confirm = async () => {
    if (!preview || status !== 'pending') return;
    setStatus('confirming'); setMessage('');
    try { const result = await onConfirm(); setReceipt(result); setStatus('executed'); setMessage('操作已执行，以下为 Core 回执。'); }
    catch (error) { setStatus(error instanceof UnknownConfirmationError ? 'unknown' : 'pending'); setMessage(error instanceof Error ? error.message : '确认失败'); }
  };
  return <Modal open={Boolean(preview)} title={preview?.display.title ? String(preview.display.title) : '确认操作'} footer={status === 'executed' ? <Button onClick={onCancel}>关闭</Button> : <><Button disabled={status === 'confirming'} onClick={onCancel}>关闭</Button>{status === 'unknown' ? <Button onClick={() => void recheck()}>重查状态</Button> : <Button disabled={status !== 'pending'} loading={status === 'confirming'} onClick={() => void confirm()} type="primary">确认执行</Button>}</>} onCancel={() => { if (status !== 'confirming') onCancel(); }}>
    {preview && <div className="preview-summary"><Tag color={preview.riskLevel === 'L2' ? 'orange' : 'blue'}>{preview.riskLevel} 风险</Tag><p>{typeof preview.display.summary === 'string' ? preview.display.summary : '请核对下方操作后确认执行。'}</p><PreviewFacts value={preview.display} /><Text type="secondary">预览有效期至 {formatDate(preview.expiresAt)}</Text>{message && <Alert className="preview-alert" message={message} type={status === 'executed' ? 'success' : 'warning'} showIcon />}{receipt && <><strong>执行回执</strong><PreviewFacts value={receipt} /></>}</div>}
  </Modal>;
}

function PreviewFacts({ value }: { value: Record<string, unknown> }) {
  const entries = Object.entries(value).filter(([key]) => key !== 'title' && key !== 'summary');
  return entries.length ? <dl className="preview-facts">{entries.map(([key, item]) => <div key={key}><dt>{key}</dt><dd>{typeof item === 'object' && item !== null ? JSON.stringify(item, null, 2) : String(item ?? '—')}</dd></div>)}</dl> : null;
}

function previewConfirmationKey(previewId: string): string {
  const key = `pianomanager.preview.idempotency.v1:${previewId}`;
  const existing = window.sessionStorage.getItem(key);
  if (existing) return existing;
  const created = idempotencyKey();
  window.sessionStorage.setItem(key, created);
  return created;
}

type PendingPreview = AssistantPreviewDraft & { success: string; invalidate: string[] };
function usePersistedPreview(section: Section) {
  const actor = window.sessionStorage.getItem('pianomanager.assistant.actor') ?? '';
  const storageKey = `pianomanager.structured-preview.v1:${encodeURIComponent(actor)}:${section}`;
  const [preview, setPreview] = useState<PendingPreview | null>(() => {
    try {
      const raw = window.sessionStorage.getItem(storageKey);
      const value: unknown = raw ? JSON.parse(raw) : null;
      if (!isRecord(value) || typeof value.previewId !== 'string' || typeof value.actionType !== 'string' || typeof value.schemaVersion !== 'string' || (value.riskLevel !== 'L1' && value.riskLevel !== 'L2') || typeof value.expiresAt !== 'string' || !isRecord(value.display) || typeof value.success !== 'string' || !Array.isArray(value.invalidate) || !value.invalidate.every((key) => typeof key === 'string')) return null;
      return { previewId: value.previewId, actionType: value.actionType, schemaVersion: value.schemaVersion, riskLevel: value.riskLevel, expiresAt: value.expiresAt, display: value.display, success: value.success, invalidate: value.invalidate, status: 'PENDING', receipt: null };
    } catch { return null; }
  });
  useEffect(() => {
    try { if (preview) window.sessionStorage.setItem(storageKey, JSON.stringify(preview)); else window.sessionStorage.removeItem(storageKey); } catch { /* storage is optional */ }
  }, [preview, storageKey]);
  return [preview, setPreview] as const;
}

export function StructuredWorkbench({ section, role }: { section: Section; role: string }) {
  if (section === 'students') return <StudentsWorkbench />;
  if (section === 'schedule') return <ScheduleWorkbench owner={role === 'OWNER'} />;
  return <FinanceWorkbench />;
}

function WorkbenchHeader({ title, description }: { title: string; description: string }) {
  return <div className="structured-heading"><div><span className="eyebrow accent-eyebrow">OPERATING DESK</span><Title level={1}>{title}</Title><p className="intro-copy">{description}</p></div></div>;
}

function ActionFeedback({ message, onClose }: { message: { type: 'success' | 'error'; text: string } | null; onClose: () => void }) {
  return message ? <Alert closable className="structured-feedback" message={message.text} onClose={onClose} showIcon type={message.type} /> : null;
}

function StudentsWorkbench() {
  const client = useQueryClient();
  const [search, setSearch] = useUrlState('q', '');
  const students = useQuery({ queryKey: ['structured-students', search], queryFn: ({ signal }) => request(`/api/students${search.trim() ? `?q=${encodeURIComponent(search.trim())}` : ''}`, (value): value is Student[] => isList(value, isStudent), { signal }) });
  const filteredStudents = students.data ?? [];
  const [selectedStudentId, setSelectedStudentId] = useUrlState('student', '');
  const selectedStudent = filteredStudents.find((student) => student.id === selectedStudentId) ?? filteredStudents[0] ?? null;
  const accounts = useQuery({ queryKey: ['student-detail-accounts', selectedStudent?.id], queryFn: () => request(`/api/students/${selectedStudent!.id}/course-accounts`, (value): value is CourseAccount[] => isList(value, isAccount)), enabled: Boolean(selectedStudent) });
  const [selectedAccountId, setSelectedAccountId] = useUrlState('account', '');
  const selectedAccount = accounts.data?.find((account) => account.id === selectedAccountId) ?? accounts.data?.[0] ?? null;
  const [tabValue, setTab] = useUrlState('tab', 'accounts');
  const tab = tabValue === 'profile' || tabValue === 'ledger' ? tabValue : 'accounts';
  const balance = useQuery({ queryKey: ['student-account-balance', selectedAccount?.id], queryFn: () => request(`/api/student-course-accounts/${selectedAccount!.id}/balance`, isBalance), enabled: Boolean(selectedAccount) });
  const ledger = useQuery({ queryKey: ['student-account-ledger', selectedAccount?.id], queryFn: () => request(`/api/student-course-accounts/${selectedAccount!.id}/ledger`, isLedger), enabled: Boolean(selectedAccount) && tab === 'ledger' });
  const [createOpen, setCreateOpen] = useState(false);
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [notes, setNotes] = useState('');
  const [editing, setEditing] = useState<Student | null>(null);
  const [accountAction, setAccountAction] = useState<'payment' | 'gift' | 'price' | 'refund' | null>(null);
  const [reversalEntry, setReversalEntry] = useState<string | null>(null);
  const [reversalReason, setReversalReason] = useState('');
  const [amount, setAmount] = useState('0.00');
  const [channel, setChannel] = useState('CASH');
  const [transactionNote, setTransactionNote] = useState('');
  const [occurredAt, setOccurredAt] = useState(localNow);
  const [pendingPreview, setPendingPreview] = usePersistedPreview('students');
  const [feedback, setFeedback] = useState<{ type: 'success' | 'error'; text: string } | null>(null);
  const submit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    try {
      const preview = await createAssistantPreview({ token: getToken(), path: 'structured-action', body: { actionType: 'student.create', command: { name, phone: phone.trim() || null, notes: notes.trim() || null }, ...browserIds() } });
      setPendingPreview({ ...preview, success: '学生已创建', invalidate: ['structured-students'] });
      setName(''); setPhone(''); setNotes(''); setCreateOpen(false);
    } catch (error) { setFeedback({ type: 'error', text: error instanceof Error ? error.message : '创建学生失败' }); }
  };
  const update = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); if (!editing) return;
    try {
      const preview = await createAssistantPreview({ token: getToken(), path: 'structured-action', body: { actionType: 'student.update', command: { studentId: editing.id, name: editing.name, phone: editing.phone?.trim() || null, notes: editing.notes?.trim() || null }, ...browserIds() } });
      setPendingPreview({ ...preview, success: '学生资料已更新', invalidate: ['structured-students'] }); setEditing(null);
    } catch (error) { setFeedback({ type: 'error', text: error instanceof Error ? error.message : '更新学生失败' }); }
  };
  const requestAccountPreview = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if (!selectedStudent) return; try { const ids = browserIds(); let path = 'structured-action'; let body: Record<string, unknown>; let success = '操作已完成'; if (accountAction === 'payment' && selectedAccount) { path = 'course-accounts/payment'; body = { accountId: selectedAccount.id, amount, channel, occurredAt: toOffsetDate(occurredAt), ...(transactionNote.trim() ? { note: transactionNote.trim() } : {}), ...ids }; success = '交费已登记'; } else if (accountAction === 'gift' && selectedAccount) { path = 'course-accounts/gift'; body = { accountId: selectedAccount.id, amount, occurredAt: toOffsetDate(occurredAt), ...ids }; success = '赠送已登记'; } else if (accountAction === 'price' && selectedAccount) { body = { actionType: 'course-account.price', command: { accountId: selectedAccount.id, currentUnitPrice: amount }, ...ids }; success = '课程单价已更新'; } else if (accountAction === 'refund') { path = 'students/final-refund'; body = { studentId: selectedStudent.id, feeAmount: amount, channel, occurredAt: toOffsetDate(occurredAt), ...(transactionNote.trim() ? { note: transactionNote.trim() } : {}), ...ids }; success = '最终退款已完成'; } else return; const preview = await createAssistantPreview({ token: getToken(), path, body }); setPendingPreview({ ...preview, success, invalidate: ['structured-students', 'student-detail-accounts', 'student-account-balance'] }); } catch (error) { setFeedback({ type: 'error', text: error instanceof Error ? error.message : '无法创建操作预览' }); } };
  const requestReversal = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!selectedAccount || !reversalEntry) return;
    try {
      const preview = await createAssistantPreview({ token: getToken(), path: 'structured-action', body: { actionType: 'ledger-entry.reversal', command: { entryId: reversalEntry, accountVersion: selectedAccount.version, occurredAt: toOffsetDate(occurredAt), reason: reversalReason }, ...browserIds() } });
      setPendingPreview({ ...preview, success: '流水已冲正', invalidate: ['student-account-balance', 'student-account-ledger', 'student-detail-accounts'] }); setReversalEntry(null); setReversalReason('');
    } catch (error) { setFeedback({ type: 'error', text: error instanceof Error ? error.message : '无法创建冲正预览' }); }
  };
  const confirmPreview = async () => { if (!pendingPreview) return null; const result = await confirmAssistantPreview({ token: getToken(), previewId: pendingPreview.previewId, idempotencyKey: previewConfirmationKey(pendingPreview.previewId) }); setFeedback({ type: 'success', text: pendingPreview.success }); for (const key of [...pendingPreview.invalidate, 'student-account-ledger', 'home-overview']) await client.invalidateQueries({ queryKey: [key] }); setAccountAction(null); return result.receipt; };
  const statusText = (status: string) => ({ STUDYING: '在读', FROZEN: '冻结', WITHDRAWN: '退学' } as Record<string, string>)[status] ?? status;
  return <section aria-labelledby="structured-heading" className="structured-view student-workspace"><div className="workspace-page-head"><WorkbenchHeader title="学生与账户" description="查找学生、查看课程账户，并把办理任务交给助手。" /><Button onClick={() => setCreateOpen(true)} type="primary">＋ 新建学生</Button></div><ActionFeedback message={feedback} onClose={() => setFeedback(null)} />
    <div className="student-toolbar"><span className="eyebrow">学生档案与课程账户</span><Input aria-label="搜索学生或联系电话" onChange={(event) => setSearch(event.target.value)} placeholder="搜索学生姓名或联系电话" value={search} /><span>{filteredStudents.length} 位学生</span></div>
    {students.isError ? <Alert message="暂时无法读取学生" description={students.error.message} type="error" showIcon /> : <div className="student-master-detail"><aside className="student-directory" aria-label="学生列表">{students.isLoading ? <div className="loading-state">正在读取学生…</div> : filteredStudents.map((student) => <button className={student.id === selectedStudent?.id ? 'is-active' : ''} key={student.id} onClick={() => { setSelectedStudentId(student.id); }} type="button"><strong>{student.name}</strong><span>{statusText(student.enrollmentStatus)} · {student.phone ? maskPhone(student.phone) : '未留电话'}</span></button>)}</aside><div className="student-detail">{selectedStudent ? <><div className="student-detail-head"><div><Title level={3}>{selectedStudent.name}</Title><p>{maskPhone(selectedStudent.phone)} · {statusText(selectedStudent.enrollmentStatus)}</p></div><Tag>{statusText(selectedStudent.enrollmentStatus)}</Tag></div><div className="workbench-tabs student-tabs" role="tablist">{([['profile','基本资料'],['accounts','课程账户'],['ledger','账户流水']] as const).map(([value,label]) => <button aria-selected={tab === value} className={tab === value ? 'is-active' : ''} key={value} onClick={() => setTab(value)} role="tab" type="button">{label}</button>)}</div>{tab === 'profile' && <div className="student-info-grid"><div><span>学生姓名</span><strong>{selectedStudent.name}</strong></div><div><span>联系电话</span><strong>{maskPhone(selectedStudent.phone)}</strong></div><div><span>学籍状态</span><strong>{statusText(selectedStudent.enrollmentStatus)}</strong></div><div><span>备注</span><strong>{selectedStudent.notes || '—'}</strong></div><Button onClick={() => setEditing({ ...selectedStudent })}>编辑资料</Button></div>}{tab === 'accounts' && <div className="course-account-view"><div className="course-switcher">{accounts.data?.map((account) => <button className={account.id === selectedAccount?.id ? 'is-active' : ''} key={account.id} onClick={() => setSelectedAccountId(account.id)} type="button"><span>{account.courseName}账户</span><strong>{account.id === selectedAccount?.id && balance.data ? `余额 ${money(balance.data.totalBalance)}` : `单价 ${money(account.currentUnitPrice)}`}</strong></button>)}</div>{selectedAccount ? <div className="focused-account-card"><div className="focused-account-head"><div><span>当前查看</span><Title level={4}>{selectedAccount.courseName}账户</Title></div><div><span>账户总余额</span><strong>{balance.isLoading ? '…' : balance.data ? money(balance.data.totalBalance) : '暂不可用'}</strong><em>按当前单价扣减</em></div></div><div className="balance-strip"><div><span>实付余额</span><strong>{balance.data ? money(balance.data.paidBalance) : '—'}</strong></div><div><span>赠送余额</span><strong>{balance.data ? money(balance.data.giftBalance) : '—'}</strong><em>上课时优先扣除</em></div><div><span>当前单价</span><strong>{money(selectedAccount.currentUnitPrice)}</strong><em>每节</em></div></div>{balance.isError && <Alert message="余额读取失败，请重试" type="error" showIcon />}<div className="account-actions"><Button onClick={() => { setAmount('0.00'); setAccountAction('payment'); }} type="primary">登记交费</Button><Button onClick={() => { setAmount('0.00'); setAccountAction('gift'); }}>登记赠送</Button><Button onClick={() => { setAmount(selectedAccount.currentUnitPrice); setAccountAction('price'); }}>修改单价</Button><Button danger onClick={() => { setAmount('0.00'); setAccountAction('refund'); }}>最终退款</Button></div></div> : accounts.isLoading ? <div className="loading-state">正在读取课程账户…</div> : accounts.isError ? <Alert message="暂时无法读取课程账户" type="error" showIcon /> : <Empty description="该学生尚未开通课程账户" />}</div>}{tab === 'ledger' && <div className="account-ledger">{!selectedAccount ? <Empty description="请先选择课程账户" /> : ledger.isLoading ? <div className="loading-state">正在读取账户流水…</div> : ledger.isError ? <Alert message="暂时无法读取账户流水" description={ledger.error.message} type="error" showIcon /> : ledger.data?.entries.length ? ledger.data.entries.map((entry) => <div className="account-ledger-row" key={entry.entryId}><div><strong>{ledgerKind(entry.kind)}</strong><span>{formatDate(entry.occurredAt)} · {entry.operator}</span>{entry.note && <small>{entry.note}</small>}</div><div><strong>{money(entry.amount)}</strong><span>实付 {entry.paidDelta} · 赠送 {entry.giftDelta}</span>{(entry.kind === 'PAYMENT' || entry.kind === 'GIFT') && <Button size="small" onClick={() => { setReversalReason(''); setReversalEntry(entry.entryId); }}>申请冲正</Button>}</div></div>) : <Empty description="当前账户暂无流水" />}</div>}</> : <Empty description="暂无学生记录" />}</div></div>}
    {accountAction && <Card className="account-action-card" title={{ payment: '登记交费', gift: '登记赠送', price: '修改课程单价', refund: '最终退款' }[accountAction]}><form className="structured-form inline-form" onSubmit={requestAccountPreview}><Input aria-label="业务金额" onChange={(event) => setAmount(event.target.value)} placeholder="0.00" value={amount} />{(accountAction === 'payment' || accountAction === 'refund') && <Select aria-label="收付款渠道" onChange={(value) => setChannel(value ?? 'CASH')} options={channels} value={channel} />}{(accountAction === 'payment' || accountAction === 'refund') && <Input aria-label="收付款备注" onChange={(event) => setTransactionNote(event.target.value)} placeholder={channel === 'OTHER' ? '其他渠道请填写备注' : '备注（可选）'} required={channel === 'OTHER'} value={transactionNote} />}{accountAction !== 'price' && <Input aria-label="业务发生时间" onChange={(event) => setOccurredAt(event.target.value)} type="datetime-local" value={occurredAt} />}<Button htmlType="submit" type="primary">生成确认单</Button><Button onClick={() => setAccountAction(null)}>取消</Button></form></Card>}
    <Modal footer={null} onCancel={() => setCreateOpen(false)} open={createOpen} title="新建学生"><form className="structured-form" onSubmit={submit}><label htmlFor="new-student-name">姓名</label><Input id="new-student-name" onChange={(event) => setName(event.target.value)} required value={name} /><label htmlFor="new-student-phone">联系电话（可选）</label><Input id="new-student-phone" onChange={(event) => setPhone(event.target.value)} value={phone} /><label htmlFor="new-student-notes">备注</label><Input.TextArea id="new-student-notes" onChange={(event) => setNotes(event.target.value)} value={notes} /><Button htmlType="submit" type="primary">创建学生</Button></form></Modal>
    <Modal footer={null} onCancel={() => setEditing(null)} open={Boolean(editing)} title={`编辑：${editing?.name ?? ''}`}>{editing && <form className="structured-form" onSubmit={update}><label htmlFor="edit-student-name">姓名</label><Input id="edit-student-name" onChange={(event) => setEditing({ ...editing, name: event.target.value })} required value={editing.name} /><label htmlFor="edit-student-phone">联系电话（可选）</label><Input id="edit-student-phone" onChange={(event) => setEditing({ ...editing, phone: event.target.value })} value={editing.phone ?? ''} /><label htmlFor="edit-student-notes">备注</label><Input.TextArea id="edit-student-notes" onChange={(event) => setEditing({ ...editing, notes: event.target.value })} value={editing.notes ?? ''} /><Button htmlType="submit" type="primary">保存修改</Button></form>}</Modal>
    <Modal footer={null} onCancel={() => setReversalEntry(null)} open={Boolean(reversalEntry)} title="冲正账户流水"><form className="structured-form" onSubmit={requestReversal}><label htmlFor="reversal-reason">冲正原因</label><Input id="reversal-reason" onChange={(event) => setReversalReason(event.target.value)} required value={reversalReason} /><label htmlFor="reversal-time">发生时间</label><Input id="reversal-time" onChange={(event) => setOccurredAt(event.target.value)} required type="datetime-local" value={occurredAt} /><Button htmlType="submit" type="primary">生成确认单</Button></form></Modal>
    <PreviewDialog preview={pendingPreview} onCancel={() => setPendingPreview(null)} onConfirm={confirmPreview} />
  </section>;
}

function ScheduleWorkbench({ owner }: { owner: boolean }) {
  const client = useQueryClient();
  const [weekValue, setWeekValue] = useUrlState('week', '');
  const start = /^\d{4}-\d{2}-\d{2}$/.test(weekValue) && Number.isFinite(Date.parse(`${weekValue}T00:00:00+08:00`)) ? weekValue : weekStart();
  const days = Array.from({ length: 7 }, (_, index) => addBusinessDays(start, index));
  const lessons = useQuery({ queryKey: ['structured-lessons', start], queryFn: ({ signal }) => request(`/api/lessons?from=${encodeURIComponent(`${start}T00:00:00+08:00`)}&to=${encodeURIComponent(`${addBusinessDays(start, 7)}T00:00:00+08:00`)}`, (value): value is Lesson[] => isList(value, isLesson), { signal }) });
  const students = useQuery({ queryKey: ['structured-students-for-schedule'], queryFn: () => request('/api/students', (value): value is Student[] => isList(value, isStudent)), enabled: owner });
  const teachers = useQuery({ queryKey: ['structured-teachers'], queryFn: () => request('/api/teachers', (value): value is Teacher[] => isList(value, isTeacher)), enabled: owner });
  const [studentId, setStudentId] = useState(''); const [accountId, setAccountId] = useState(''); const [teacherId, setTeacherId] = useState(''); const [startsAt, setStartsAt] = useState(''); const [selectedLessonId, setSelectedLessonId] = useUrlState('lesson', ''); const selectedLesson = lessons.data?.find((lesson) => lesson.id === selectedLessonId) ?? null; const [newStartsAt, setNewStartsAt] = useState('');
  const [createOpen, setCreateOpen] = useState(false); const [rescheduleOpen, setRescheduleOpen] = useState(false); const [statusFilter, setStatusFilter] = useUrlState('status', 'ALL'); const [scheduleMode, setScheduleMode] = useState<'single' | 'weekly'>('single'); const [weeks, setWeeks] = useState(4);
  const [feedback, setFeedback] = useState<{ type: 'success' | 'error'; text: string } | null>(null);
  const [pendingPreview, setPendingPreview] = usePersistedPreview('schedule');
  const accounts = useQuery({ queryKey: ['structured-accounts', studentId], queryFn: () => request(`/api/students/${studentId}/course-accounts`, (value): value is CourseAccount[] => isList(value, isAccount)), enabled: Boolean(studentId) });
  const requestPreview = async (path: string, command: Record<string, unknown>, success: string) => { try { const ids = browserIds(); const preview = await createAssistantPreview({ token: getToken(), path, body: { ...command, ...ids } }); setPendingPreview({ ...preview, success, invalidate: ['structured-lessons'] }); setFeedback(null); return true; } catch (error) { setFeedback({ type: 'error', text: error instanceof Error ? error.message : '无法创建操作预览' }); return false; } };
  const confirmPreview = async () => { if (!pendingPreview) return null; const result = await confirmAssistantPreview({ token: getToken(), previewId: pendingPreview.previewId, idempotencyKey: previewConfirmationKey(pendingPreview.previewId) }); setFeedback({ type: 'success', text: pendingPreview.success }); for (const key of [...pendingPreview.invalidate, 'home-overview']) await client.invalidateQueries({ queryKey: [key] }); return result.receipt; };
  const create = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const created = await requestPreview(scheduleMode === 'weekly' ? 'lessons/batch' : 'lessons/single', scheduleMode === 'weekly' ? { accountId, teacherId, firstStartsAt: toOffsetDate(startsAt), weeks } : { accountId, teacherId, startsAt: toOffsetDate(startsAt) }, scheduleMode === 'weekly' ? `已创建 ${weeks} 周排课` : '排课已创建'); if (created) { setStudentId(''); setAccountId(''); setTeacherId(''); setStartsAt(''); setCreateOpen(false); } };
  const reschedule = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if (!selectedLesson || !newStartsAt) return; const created = await requestPreview('lessons/reschedule', { lessonId: selectedLesson.id, startsAt: toOffsetDate(newStartsAt) }, '排课时间已调整'); if (created) { setRescheduleOpen(false); setNewStartsAt(''); } };
  const visibleLessons = (lessons.data ?? []).filter((lesson) => days.includes(businessDate(new Date(lesson.startsAt))) && (statusFilter === 'ALL' || lesson.status === statusFilter));
  const statusText = (value: string) => ({ SCHEDULED: '待上课', COMPLETED: '已完成', CANCELLED: '已取消' } as Record<string, string>)[value] ?? value;
  return <section aria-labelledby="structured-heading" className="structured-view schedule-workspace"><div className="workspace-page-head"><WorkbenchHeader title="排课与课消" description="按自然周查看七天课程，完成排课、调课、请假与课消确认。" />{owner && <Button onClick={() => setCreateOpen(true)} type="primary">＋ 新建排课</Button>}</div><ActionFeedback message={feedback} onClose={() => setFeedback(null)} />
    <div className="schedule-toolbar"><div><Button onClick={() => setWeekValue(addBusinessDays(start, -7))}>上一周</Button><Button onClick={() => setWeekValue(weekStart())}>本周</Button><Button onClick={() => setWeekValue(addBusinessDays(start, 7))}>下一周</Button></div><strong>{start} — {days[6]}</strong><Select aria-label="课程状态筛选" onChange={(value) => setStatusFilter(value ?? 'ALL')} options={[{ label: '全部状态', value: 'ALL' }, { label: '待上课', value: 'SCHEDULED' }, { label: '已完成', value: 'COMPLETED' }, { label: '已取消', value: 'CANCELLED' }]} value={statusFilter} /></div>
    {lessons.isError ? <Alert message="暂时无法读取排课" description={lessons.error.message} type="error" showIcon /> : <div className="week-board" aria-label="七天排课周视图">{days.map((day, index) => { const dayLessons = visibleLessons.filter((lesson) => businessDate(new Date(lesson.startsAt)) === day); return <section className={day === businessDate() ? 'week-day is-today' : 'week-day'} key={day}><header><span>周{['一','二','三','四','五','六','日'][index]}</span><strong>{day.slice(5)}</strong><em>{dayLessons.length} 节</em></header><div>{dayLessons.length ? dayLessons.map((lesson) => <button className={`lesson-chip status-${lesson.status.toLowerCase()}`} key={lesson.id} onClick={() => setSelectedLessonId(lesson.id)} type="button"><time>{new Intl.DateTimeFormat('zh-CN', { timeZone: 'Asia/Shanghai', hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date(lesson.startsAt))}</time><strong>{lesson.student.name}</strong><span>{lesson.course.name}</span><em>{statusText(lesson.status)}</em></button>) : <span className="day-empty">无排课</span>}</div></section>; })}</div>}
    {selectedLesson && <Card className="lesson-detail-card" title={`${selectedLesson.student.name} · ${selectedLesson.course.name}`} extra={<Button size="small" onClick={() => setSelectedLessonId('')}>关闭</Button>}><div className="lesson-detail-grid"><div><span>上课时间</span><strong>{formatDate(selectedLesson.startsAt)}</strong></div><div><span>课程状态</span><strong>{statusText(selectedLesson.status)}</strong></div><div><span>课消单价</span><strong>{selectedLesson.unitPriceSnapshot ? money(selectedLesson.unitPriceSnapshot) : '待上课时锁定'}</strong></div></div>{selectedLesson.status === 'SCHEDULED' && <div className="account-actions"><Button onClick={() => { setNewStartsAt(''); setRescheduleOpen(true); }}>调整时间</Button><Button onClick={() => void requestPreview('lessons/cancel', { lessonId: selectedLesson.id }, '排课已取消')}>请假 / 取消</Button><Button type="primary" onClick={() => void requestPreview('lessons/complete', { lessonId: selectedLesson.id }, '课程已确认完成')}>确认上课</Button></div>}{owner && selectedLesson.status === 'COMPLETED' && <Button danger onClick={() => void requestPreview('structured-action', { actionType: 'lesson.complete.reversal', command: { lessonId: selectedLesson.id } }, '已撤销上课确认')}>撤销上课确认</Button>}</Card>}
    <Modal footer={null} onCancel={() => setCreateOpen(false)} open={createOpen} title="新建排课"><form className="structured-form" onSubmit={create}><label htmlFor="schedule-mode">排课方式</label><Select id="schedule-mode" onChange={(value) => setScheduleMode(value ?? 'single')} options={[{ label: '单节排课', value: 'single' }, { label: '每周重复', value: 'weekly' }]} value={scheduleMode} /><label htmlFor="schedule-student">学生</label><Select id="schedule-student" onChange={(value) => { setStudentId(value ?? ''); setAccountId(''); }} options={students.data?.map((student) => ({ label: student.name, value: student.id })) ?? []} placeholder="选择学生" value={studentId || null} /><label htmlFor="schedule-account">课程账户</label><Select id="schedule-account" disabled={!studentId || accounts.isLoading} onChange={(value) => setAccountId(value ?? '')} options={accounts.data?.map((account) => ({ label: `${account.courseName}（${account.defaultDurationMinutes} 分钟）`, value: account.id })) ?? []} placeholder="选择课程" value={accountId || null} /><label htmlFor="schedule-teacher">教师</label><Select id="schedule-teacher" onChange={(value) => setTeacherId(value ?? '')} options={teachers.data?.filter((teacher) => teacher.isActive).map((teacher) => ({ label: teacher.name, value: teacher.id })) ?? []} placeholder="选择教师" value={teacherId || null} /><label htmlFor="schedule-time">{scheduleMode === 'weekly' ? '首次开始时间' : '开始时间'}</label><Input id="schedule-time" onChange={(event) => setStartsAt(event.target.value)} type="datetime-local" value={startsAt} />{scheduleMode === 'weekly' && <><label htmlFor="schedule-weeks">重复周数（1-52）</label><Input id="schedule-weeks" max={52} min={1} onChange={(event) => setWeeks(Number(event.target.value))} type="number" value={weeks} /></>}<Button disabled={!studentId || !accountId || !teacherId || !startsAt || (scheduleMode === 'weekly' && (weeks < 1 || weeks > 52))} htmlType="submit" type="primary">生成确认单</Button></form></Modal>
    <Modal footer={null} onCancel={() => setRescheduleOpen(false)} open={rescheduleOpen && Boolean(selectedLesson)} title={`调课：${selectedLesson?.student.name ?? ''}`}><form className="structured-form" onSubmit={reschedule}><label htmlFor="reschedule-time">新的开始时间</label><Input id="reschedule-time" onChange={(event) => setNewStartsAt(event.target.value)} required type="datetime-local" value={newStartsAt} /><Button htmlType="submit" type="primary">生成确认单</Button></form></Modal>
    <PreviewDialog preview={pendingPreview} onCancel={() => setPendingPreview(null)} onConfirm={confirmPreview} />
  </section>;
}

const incomeCategories = [{ label: '卖书', value: 'BOOK_SALE' }, { label: '卖琴', value: 'INSTRUMENT_SALE' }, { label: '外部合作', value: 'EXTERNAL_COOPERATION' }, { label: '其他经营收入', value: 'OTHER_INCOME' }];
const expenseCategories = [{ label: '房租物业', value: 'RENT_PROPERTY' }, { label: '水电网络', value: 'UTILITIES_NETWORK' }, { label: '营销', value: 'MARKETING' }, { label: '办公用品', value: 'OFFICE_SUPPLIES' }, { label: '维修', value: 'MAINTENANCE' }, { label: '图书采购成本', value: 'BOOK_PURCHASE_COST' }, { label: '琴类采购成本', value: 'INSTRUMENT_PURCHASE_COST' }, { label: '外部合作成本', value: 'EXTERNAL_COOPERATION_COST' }, { label: '其他支出', value: 'OTHER_EXPENSE' }];
const channels = [{ label: '现金', value: 'CASH' }, { label: '微信', value: 'WECHAT' }, { label: '支付宝', value: 'ALIPAY' }, { label: '银行卡', value: 'BANK_CARD' }, { label: '其他', value: 'OTHER' }];
function displayOption(options: Array<{ label: string; value: string }>, value: string | null | undefined): string {
  if (!value) return '—';
  return options.find((option) => option.value === value)?.label ?? value;
}

function FinanceWorkbench() {
  const client = useQueryClient(); const [period, setPeriod] = useUrlState('period', monthNow()); const [tabValue, setTab] = useUrlState('tab', 'report'); const tab = tabValue === 'payroll' || tabValue === 'manual' || tabValue === 'periods' ? tabValue : 'report'; const [feedback, setFeedback] = useState<{ type: 'success' | 'error'; text: string } | null>(null); const [pendingPreview, setPendingPreview] = usePersistedPreview('finance');
  const report = useQuery({ queryKey: ['structured-report', period], queryFn: () => request(`/api/reports/monthly?period=${encodeURIComponent(period)}`, isReport), enabled: /^\d{4}-\d{2}$/.test(period) });
  const payroll = useQuery({ queryKey: ['structured-payroll', period], queryFn: () => request(`/api/payrolls?period=${encodeURIComponent(period)}`, (value): value is Payroll[] => isList(value, isPayroll)), enabled: tab === 'payroll' });
  const manual = useQuery({ queryKey: ['structured-manual', period], queryFn: () => request(`/api/manual-transactions?from=${encodeURIComponent(`${period}-01T00:00:00+08:00`)}&to=${encodeURIComponent(`${nextMonth(period)}-01T00:00:00+08:00`)}`, (value): value is ManualTransaction[] => isList(value, isManualTransaction)), enabled: tab === 'manual' });
  const periods = useQuery({ queryKey: ['structured-periods'], queryFn: () => request('/api/periods', (value): value is ClosedPeriod[] => isList(value, isClosedPeriod)), enabled: tab === 'periods' });
  const preclose = useQuery({ queryKey: ['structured-preclose', period], queryFn: () => request(`/api/periods/preclose?period=${encodeURIComponent(period)}`, isPeriodCloseReadiness), enabled: tab === 'periods' && /^\d{4}-\d{2}$/.test(period) });
  const teachers = useQuery({ queryKey: ['structured-finance-teachers'], queryFn: () => request('/api/teachers', (value): value is Teacher[] => isList(value, isTeacher)), enabled: tab === 'payroll' });
  const requestPreview = async (path: string, body: Record<string, unknown>, success: string, invalidate: string[]) => { try { const preview = await createAssistantPreview({ token: getToken(), path, body: { ...body, ...browserIds() } }); setPendingPreview({ ...preview, success, invalidate }); } catch (error) { setFeedback({ type: 'error', text: error instanceof Error ? error.message : '无法创建操作预览' }); } };
  const confirmPreview = async () => { if (!pendingPreview) return null; const result = await confirmAssistantPreview({ token: getToken(), previewId: pendingPreview.previewId, idempotencyKey: previewConfirmationKey(pendingPreview.previewId) }); setFeedback({ type: 'success', text: pendingPreview.success }); for (const key of [...pendingPreview.invalidate, 'structured-preclose', 'home-overview']) await client.invalidateQueries({ queryKey: [key] }); return result.receipt; };
  const financeTabs = [['report', '经营概览', '经营口径与现金口径'], ['manual', '收支流水', '手工收支与明细'], ['payroll', '工资', '生成、核对与支付'], ['periods', '关账', '月末检查与锁定']] as const;
  return <section aria-labelledby="structured-heading" className="structured-view finance-workspace"><div className="workspace-page-head"><WorkbenchHeader title="收支与报表" description="同屏核对经营结果与现金变化，处理工资、流水和月末关账。" /><label className="period-control">业务月份<Input aria-label="报表月份" onChange={(event) => setPeriod(event.target.value)} type="month" value={period} /></label></div><ActionFeedback message={feedback} onClose={() => setFeedback(null)} /><div className="finance-nav" role="tablist">{financeTabs.map(([value, label, description], index) => <button aria-label={value === 'manual' ? '手工收支' : label} aria-selected={tab === value} className={tab === value ? 'is-active' : ''} key={value} onClick={() => setTab(value)} role="tab" type="button"><span>0{index + 1}</span><strong>{label}</strong><em>{description}</em></button>)}</div>{tab === 'report' && <ReportPanel report={report.data} loading={report.isLoading} error={report.error} />}{tab === 'payroll' && <PayrollPanel period={period} payroll={payroll.data} teachers={teachers.data} loading={payroll.isLoading} onPreview={requestPreview} />}{tab === 'manual' && <ManualPanel period={period} transactions={manual.data} loading={manual.isLoading} onPreview={requestPreview} />}{tab === 'periods' && <PeriodsPanel period={period} periods={periods.data} readiness={preclose.data} loading={periods.isLoading} onPreview={requestPreview} />}<PreviewDialog preview={pendingPreview} onCancel={() => setPendingPreview(null)} onConfirm={confirmPreview} /></section>;
}

function ReportPanel({ report, loading, error }: { report: Report | undefined; loading: boolean; error: Error | null }) { return <>{loading && <Card className="data-card"><div className="loading-state" role="status">正在读取月报…</div></Card>}{error && <Alert message="暂时无法读取月报" description={error.message} type="error" showIcon />}{report && <div aria-label="月度财务报表" className="finance-overview"><Card className="finance-basis-card operating-card" variant="borderless"><span className="eyebrow">OPERATING BASIS</span><Title level={3}>经营结果</Title><div className="finance-primary"><span>经营利润</span><strong>{money(report.operatingProfit)}</strong></div><dl><div><dt>课消收入</dt><dd>{money(report.lessonIncome)}</dd></div><div><dt>退费手续费收入</dt><dd>{money(report.refundFeeIncome)}</dd></div><div><dt>其他经营收入</dt><dd>{money(report.manualIncome)}</dd></div><div><dt>工资成本</dt><dd>{money(report.payrollCost)}</dd></div><div><dt>赠送成本</dt><dd>{money(report.giftCost)}</dd></div><div><dt>其他经营支出</dt><dd>{money(report.manualExpense)}</dd></div></dl></Card><Card className="finance-basis-card cash-card" variant="borderless"><span className="eyebrow">CASH BASIS</span><Title level={3}>现金变化</Title><div className="finance-primary"><span>现金净额</span><strong>{money(report.cashNet)}</strong></div><dl><div><dt>现金收入</dt><dd>{money(report.cashIncome)}</dd></div><div><dt>现金支出</dt><dd>{money(report.cashExpense)}</dd></div></dl><p>经营口径按课消和当期成本确认，现金口径按实际收付款确认；两者不应混为同一指标。</p></Card></div>}</>; }

function PayrollPanel({ period, payroll, teachers, loading, onPreview }: { period: string; payroll: Payroll[] | undefined; teachers: Teacher[] | undefined; loading: boolean; onPreview: (path: string, body: Record<string, unknown>, success: string, invalidate: string[]) => Promise<void> }) { const [teacherId, setTeacherId] = useState(''); const [selected, setSelected] = useState<Payroll | null>(null); const [cancelPayment, setCancelPayment] = useState<Payroll | null>(null); const [cancelReason, setCancelReason] = useState(''); const [paidAt, setPaidAt] = useState(localNow); const [channel, setChannel] = useState('CASH'); const [note, setNote] = useState(''); return <div className="finance-panel"><Card className="data-card" title="生成工资"><form className="structured-form inline-form" onSubmit={(event) => { event.preventDefault(); if (teacherId) void onPreview('structured-action', { actionType: 'payroll.generate', command: { teacherId, period } }, '工资已生成', ['structured-payroll']); }}><Select aria-label="工资教师" onChange={(value) => setTeacherId(value ?? '')} options={teachers?.filter((teacher) => teacher.isActive).map((teacher) => ({ label: teacher.name, value: teacher.id })) ?? []} placeholder="选择教师" value={teacherId || null} /><Button disabled={!teacherId} htmlType="submit" type="primary">生成本月工资</Button></form></Card><Card className="data-card" title="工资单" loading={loading}>{payroll && <Table<Payroll> aria-label="工资列表" columns={[{ title: '教师', dataIndex: 'teacherName' }, { title: '课消收入', dataIndex: 'courseRevenue', render: money }, { title: '实发', dataIndex: 'netSalary', render: money }, { title: '状态', dataIndex: 'status', render: (value) => <Tag>{value === 'PAID' ? '已支付' : '未支付'}</Tag> }, { title: '操作', render: (_value, record) => record.status === 'UNPAID' ? <Button size="small" onClick={() => setSelected(record)}>登记支付</Button> : <Button size="small" onClick={() => { setCancelReason(''); setCancelPayment(record); }}>撤销支付</Button> }]} expandable={{ expandedRowRender: (record) => <div className="payroll-breakdown">{[['基本工资', record.baseSalary], ['课消提成', record.commissionAmount], ['奖金', record.bonusAmount], ['代扣', record.deductionAmount], ['应发工资', record.grossSalary], ['实发工资', record.netSalary]].map(([label, value]) => <div key={label}><span>{label}</span><strong>{money(value ?? '')}</strong></div>)}<p>提成比例 {record.commissionRate}% · {record.paidAt ? `支付时间 ${formatDate(record.paidAt)}` : '尚未支付'}</p></div> }} dataSource={payroll} rowKey="id" locale={{ emptyText: <Empty description="本月暂无工资记录" /> }} pagination={{ pageSize: 10 }} />}</Card>{selected && <Card className="data-card" title={`登记工资支付：${selected.teacherName}`}><form className="structured-form inline-form" onSubmit={(event) => { event.preventDefault(); void onPreview('structured-action', { actionType: 'payroll.pay', command: { payrollId: selected.id, paidAt: toOffsetDate(paidAt), channel, ...(note.trim() ? { note: note.trim() } : {}) } }, '工资支付已登记', ['structured-payroll', 'structured-report']); setSelected(null); }}><Input aria-label="工资支付时间" onChange={(event) => setPaidAt(event.target.value)} type="datetime-local" value={paidAt} /><Select aria-label="工资支付渠道" onChange={(value) => setChannel(value ?? 'CASH')} options={channels} value={channel} /><Input aria-label="工资支付备注" onChange={(event) => setNote(event.target.value)} placeholder={channel === 'OTHER' ? '其他渠道请填写备注' : '备注（可选）'} required={channel === 'OTHER'} value={note} /><Button htmlType="submit" type="primary">确认支付登记</Button><Button onClick={() => setSelected(null)}>取消</Button></form></Card>}{cancelPayment && <Card className="data-card" title={`撤销工资支付：${cancelPayment.teacherName}`}><form className="structured-form inline-form" onSubmit={(event) => { event.preventDefault(); void onPreview('structured-action', { actionType: 'payroll.cancel-payment', command: { payrollId: cancelPayment.id, reason: cancelReason.trim() } }, '工资支付已撤销', ['structured-payroll', 'structured-report']); setCancelPayment(null); }}><Input aria-label="撤销工资支付原因" onChange={(event) => setCancelReason(event.target.value)} placeholder="填写撤销原因" required value={cancelReason} /><Button disabled={!cancelReason.trim()} htmlType="submit" type="primary">生成确认单</Button><Button onClick={() => setCancelPayment(null)}>取消</Button></form></Card>}</div>; }

function ManualPanel({ period, transactions, loading, onPreview }: { period: string; transactions: ManualTransaction[] | undefined; loading: boolean; onPreview: (path: string, body: Record<string, unknown>, success: string, invalidate: string[]) => Promise<void> }) { const [kind, setKind] = useState<'INCOME' | 'EXPENSE'>('INCOME'); const [category, setCategory] = useState('BOOK_SALE'); const [amount, setAmount] = useState('0.00'); const [channel, setChannel] = useState('CASH'); const [occurredAt, setOccurredAt] = useState(localNow); const [note, setNote] = useState(''); const categories = kind === 'INCOME' ? incomeCategories : expenseCategories; return <div className="finance-panel"><Card className="data-card" title="登记手工收支"><form className="structured-form inline-form" onSubmit={(event) => { event.preventDefault(); const body = { kind, amount, channel, occurredAt: toOffsetDate(occurredAt), ...(kind === 'INCOME' ? { incomeCategory: category } : { expenseCategory: category }), ...(note.trim() ? { note: note.trim() } : {}) }; void onPreview('structured-action', { actionType: 'manual-transaction.create', command: body }, '手工收支已登记', ['structured-manual', 'structured-report']); }}><Select aria-label="收支类型" onChange={(value: 'INCOME' | 'EXPENSE') => { setKind(value); setCategory(value === 'INCOME' ? 'BOOK_SALE' : 'RENT_PROPERTY'); }} options={[{ label: '收入', value: 'INCOME' }, { label: '支出', value: 'EXPENSE' }]} value={kind} /><Select aria-label="收支分类" onChange={(value) => setCategory(value ?? 'BOOK_SALE')} options={categories} value={category} /><Input aria-label="金额" onChange={(event) => setAmount(event.target.value)} placeholder="100.00" value={amount} /><Select aria-label="收支渠道" onChange={(value) => setChannel(value ?? 'CASH')} options={channels} value={channel} /><Input aria-label="发生时间" onChange={(event) => setOccurredAt(event.target.value)} type="datetime-local" value={occurredAt} /><Input aria-label="备注" onChange={(event) => setNote(event.target.value)} placeholder={channel === 'OTHER' ? '其他渠道请填写备注' : '备注（可选）'} required={channel === 'OTHER'} value={note} /><Button htmlType="submit" type="primary">登记收支</Button></form></Card><Card className="data-card" title={`${period} 手工收支`} loading={loading}>{transactions && <Table<ManualTransaction> aria-label="手工收支列表" columns={[{ title: '发生时间', dataIndex: 'occurredAt', render: formatDate }, { title: '类型', dataIndex: 'kind', render: (value) => value === 'INCOME' ? '收入' : '支出' }, { title: '分类', render: (_value, record) => displayOption(record.kind === 'INCOME' ? incomeCategories : expenseCategories, record.incomeCategory ?? record.expenseCategory) }, { title: '金额', dataIndex: 'amount', render: money }, { title: '渠道', dataIndex: 'channel', render: (value: string) => displayOption(channels, value) }, { title: '备注', dataIndex: 'note', render: (value) => value || '—' }]} dataSource={transactions} rowKey="id" locale={{ emptyText: '本月暂无手工收支' }} pagination={{ pageSize: 10 }} />}</Card></div>; }

function PeriodsPanel({ period, periods, readiness, loading, onPreview }: { period: string; periods: ClosedPeriod[] | undefined; readiness: PeriodCloseReadiness | undefined; loading: boolean; onPreview: (path: string, body: Record<string, unknown>, success: string, invalidate: string[]) => Promise<void> }) { const [reopen, setReopen] = useState<ClosedPeriod | null>(null); const [reason, setReason] = useState(''); return <div className="finance-panel"><Card className="data-card" title={`月度关账 · ${period}`}>{!readiness ? <Alert type="info" showIcon message="正在读取关账检查，暂不可关账" /> : readiness.closed ? <Alert type="info" showIcon message="当前月份已关账" /> : readiness.blockers.length ? <Alert type="warning" showIcon message="当前月份不能关账" description={<ul>{readiness.blockers.map((item) => <li key={item.code}>{item.message}</li>)}</ul>} /> : <Alert type="success" showIcon message="当前月份可关账" description="待确认课程、工资、退款和账户流水一致性均已检查。" />}{readiness && <div className="preclose-checks">{[['待确认课程', readiness.pendingLessons.length], ['未生成工资', readiness.missingPayrollTeachers.length], ['未支付工资', readiness.unpaidPayrolls.length], ['退款异常', readiness.refundAnomalies.length], ['流水异常', readiness.ledgerAnomalies.length]].map(([label, count]) => <div key={label}><strong>{label}</strong><span>{count ? `${count} 项待处理` : '已通过'}</span></div>)}</div>}<form className="structured-form inline-form" onSubmit={(event) => { event.preventDefault(); void onPreview('structured-action', { actionType: 'period.close', command: { period } }, '月份已关账', ['structured-periods']); }}><span>检查并关账：{period}</span><Button disabled={!readiness || readiness.closed || readiness.period !== period || readiness.blockers.length > 0} htmlType="submit" type="primary">关账</Button></form><Text className="form-help">关账会阻止该业务月份的资金、课消等历史写入；存在待确认课程或未支付工资时会阻断。</Text></Card><Card className="data-card" title="已关账月份" loading={loading}>{periods && <Table<ClosedPeriod> aria-label="关账列表" columns={[{ title: '月份', dataIndex: 'period' }, { title: '关账时间', dataIndex: 'closedAt', render: formatDate }, { title: '状态', render: (_value, record) => <Tag>{record.reopenedAt ? '已重新打开' : '已关账'}</Tag> }, { title: '操作', render: (_value, record) => !record.reopenedAt ? <Button size="small" onClick={() => setReopen(record)}>重新打开</Button> : '—' }]} dataSource={periods} rowKey="period" locale={{ emptyText: <Empty description="暂无关账记录" /> }} pagination={{ pageSize: 10 }} />}</Card>{reopen && <Card className="data-card" title={`重新打开 ${reopen.period}`}><form className="structured-form inline-form" onSubmit={(event) => { event.preventDefault(); void onPreview('structured-action', { actionType: 'period.reopen', command: { period: reopen.period, reason } }, '月份已重新打开', ['structured-periods']); setReopen(null); setReason(''); }}><Input aria-label="重新打开原因" onChange={(event) => setReason(event.target.value)} placeholder="填写原因" required value={reason} /><Button htmlType="submit" type="primary">确认重新打开</Button><Button onClick={() => setReopen(null)}>取消</Button></form></Card>}</div>; }

function nextMonth(period: string): string { const [yearText = '0', monthText = '0'] = period.split('-'); const date = new Date(Date.UTC(Number(yearText), Number(monthText), 1)); return `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, '0')}`; }
